import{_ as s,o as a,c as e,a0 as i}from"./chunks/framework.DQOulFGV.js";const E=JSON.parse('{"title":"ES 性能优化","description":"","frontmatter":{"doc_id":"es-性能优化","title":"ES 性能优化"},"headers":[],"relativePath":"elasticsearch/07-性能优化.md","filePath":"elasticsearch/07-性能优化.md"}'),r={name:"elasticsearch/07-性能优化.md"};function n(l,t,d,o,h,p){return a(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="es-性能优化" tabindex="-1">ES 性能优化 <a class="header-anchor" href="#es-性能优化" aria-label="Permalink to &quot;ES 性能优化&quot;">​</a></h1><hr><h2 id="写入优化" tabindex="-1">写入优化 <a class="header-anchor" href="#写入优化" aria-label="Permalink to &quot;写入优化&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    subgraph 写入优化手段</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        A[&quot;bulk 批量写入&lt;br&gt;减少网络往返次数&quot;] --&gt; Perf[&quot;写入性能提升&lt;br&gt;5~10倍&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        B[&quot;增大 refresh_interval&lt;br&gt;默认1s → 30s或-1&lt;br&gt;减少 segment 生成频率&quot;] --&gt; Perf</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        C[&quot;增大 translog flush 间隔&lt;br&gt;降低磁盘 IO&quot;] --&gt; Perf</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        D[&quot;关闭副本&lt;br&gt;写入完成后再开启&quot;] --&gt; Perf</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    end</span></span></code></pre></div><blockquote><p><strong>为什么 refresh_interval 默认是 1 秒</strong>：ES 是&quot;近实时&quot;搜索，1 秒的延迟对大多数搜索场景可接受，同时避免频繁生成 segment（每次 refresh 都会生成新 segment，segment 过多会影响查询性能）。批量写入时可以临时设为 -1（不自动 refresh），写完后手动 refresh。</p></blockquote><hr><h2 id="查询优化" tabindex="-1">查询优化 <a class="header-anchor" href="#查询优化" aria-label="Permalink to &quot;查询优化&quot;">​</a></h2><table tabindex="0"><thead><tr><th>优化手段</th><th>原理</th><th>适用场景</th></tr></thead><tbody><tr><td>使用 filter 替代 query</td><td>filter 结果可缓存，不计算得分</td><td>纯过滤场景（状态、标签筛选）</td></tr><tr><td>避免深度分页</td><td><code>from=10000</code> 需要每个分片返回 10000 条再合并</td><td>使用 <code>search_after</code> 替代 from/size</td></tr><tr><td>减少返回字段</td><td>使用 <code>_source includes</code> 只返回需要的字段</td><td>文档字段多但只需部分字段</td></tr><tr><td>合理设置分片数</td><td>分片过多增加协调开销</td><td>单分片建议 10~50GB</td></tr></tbody></table><hr><h2 id="深度分页问题-深度分析" tabindex="-1">深度分页问题（深度分析） <a class="header-anchor" href="#深度分页问题-深度分析" aria-label="Permalink to &quot;深度分页问题（深度分析）&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Client[&quot;查询 from=10000, size=10&quot;] --&gt; Coord[&quot;协调节点&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Coord --&gt; S1[&quot;Shard 1&lt;br&gt;返回前 10010 条&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Coord --&gt; S2[&quot;Shard 2&lt;br&gt;返回前 10010 条&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Coord --&gt; S3[&quot;Shard 3&lt;br&gt;返回前 10010 条&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S1 --&gt; Merge[&quot;协调节点合并&lt;br&gt;30030 条 → 取第 10001~10010&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S2 --&gt; Merge</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S3 --&gt; Merge</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Merge --&gt; Client</span></span></code></pre></div><blockquote><p><strong>为什么深度分页性能差</strong>：每个分片都要返回前 N 条数据到协调节点，协调节点合并后再取目标页。分片越多、页码越深，内存和网络开销越大。<code>from=10000, size=10</code> 时，3 个分片需要传输 30030 条数据，只用了 10 条。</p><p><strong>解决方案</strong>：使用 <code>search_after</code>（游标分页），基于上一页最后一条记录的排序值继续查询，每次只传输 <code>size</code> 条数据，性能稳定。</p></blockquote><hr><h2 id="常见性能问题汇总" tabindex="-1">常见性能问题汇总 <a class="header-anchor" href="#常见性能问题汇总" aria-label="Permalink to &quot;常见性能问题汇总&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误场景</th><th>原因</th><th>解决方案</th></tr></thead><tbody><tr><td>主分片数设置过少，后期无法扩展</td><td>主分片数创建后不可修改（路由公式依赖分片数）</td><td>初始规划时按未来 3 年数据量估算</td></tr><tr><td>深度分页超时或 OOM</td><td>每个分片返回大量数据到协调节点合并</td><td>使用 search_after 替代 from/size</td></tr><tr><td>写入慢，refresh_interval 设置过短</td><td>每秒生成新 segment，频繁 merge</td><td>批量写入时临时设置 refresh_interval=-1</td></tr><tr><td>集群 Yellow 状态，误以为故障</td><td>单节点副本无法分配（主副不能在同一节点）</td><td>开发环境设置副本数为 0</td></tr></tbody></table><hr><h2 id="问题-es-写入数据后为什么不能立即查到" tabindex="-1">问题：ES 写入数据后为什么不能立即查到？ <a class="header-anchor" href="#问题-es-写入数据后为什么不能立即查到" aria-label="Permalink to &quot;问题：ES 写入数据后为什么不能立即查到？&quot;">​</a></h2><blockquote><p>ES 写入流程：数据先写入内存 buffer → 每隔 <code>refresh_interval</code>（默认1秒）刷新到 segment（此时可查）→ 再通过 flush 持久化到磁盘。所以 ES 是<strong>近实时</strong>（Near Real-Time）搜索，默认有约 1 秒延迟。</p></blockquote>`,18)])])}const g=s(r,[["render",n]]);export{E as __pageData,g as default};
